# Enhance database.py - add Device model after Base declaration
import json

with open('C:\\Users\\Mahantesh\\DevelopmentProjects\\Aegis\\backend\\database.py', 'r', encoding='utf-8') as f:
    content = f.read()

# Find the position after "Base = declarative_base()" and insert Device model
insert_marker = "\n# Base class for all ORM models\nBase = declarative_base()\n\n# Ensure all models are registered with Base\n"

device_model = '''\n# Device model for digital twin assets (sensors, rovers, actuators)\n# Enhanced with position tracking, asset ratios, battery, payload, and status monitoring\nclass Device(Base):\n    \"\"\"Digital twin device model representing sensors, rovers, and assets.\"\"\"\n    __tablename__ = \"devices\"\n\n    id = Column(Integer, primary_key=True, autoincrement=True)\n    device_type = Column(String(50), nullable=False)  # sensor, rover, zone, actuator\n    subtype = Column(String(50), nullable=True)  # soil_moisture, temperature, autonomous, etc.\n    zone_id = Column(String(50), nullable=True)  # FK to zones.zone_id\n\n    # Device identification\n    device_id = Column(String(100), unique=True, nullable=False)  # sensor_1, rover_1, etc.\n    name = Column(String(100), nullable=False)\n\n    # Position tracking (meters in digital twin coordinate system)\n    position_x = Column(Float, default=0.0, nullable=False)\n    position_y = Column(Float, default=0.0, nullable=False)\n    position_z = Column(Float, default=0.0, nullable=False)\n\n    # Status monitoring\n    status = Column(String, default=\"idle\", nullable=False)  # active, idle, fault, moving, charging\n\n    # Asset ratio: model : real-world scaling\n    asset_ratio = Column(String, default=\"1:1\", nullable=False)\n\n    # Sensor readings\n    last_reading = Column(Float, default=0.0, nullable=False)\n    units = Column(String, default=\"\", nullable=False)\n\n    # Rover-specific fields\n    battery_level = Column(Float, default=100.0, nullable=True)  # 0-100 percent\n    payload_capacity = Column(String, default=\"\", nullable=True)  # e.g., \"20kg\"\n    max_speed_m_s = Column(Float, default=0.0, nullable=True)\n\n    # Environment\n    environment_data = Column(Text, nullable=True)  # JSON: {\"weather\": \"clear\", \"temp\": 22}\n\n    # Relationships\n    zone = relationship(\"Zone\", foreign_keys=[zone_id])\n\n    def to_dict(self):\n        \"\"\"Convert device to dictionary for API responses.\"\"\"\n        return {\n            \"id\": self.id,\n            \"device_type\": self.device_type,\n            \"subtype\": self.subtype,\n            \"zone_id\": self.zone_id,\n            \"device_id\": self.device_id,\n            \"position\": {\"x\": self.position_x, \"y\": self.position_y, \"z\": self.position_z},\n            \"status\": self.status,\n            \"asset_ratio\": self.asset_ratio,\n            \"last_reading\": self.last_reading,\n            \"units\": self.units,\n            \"battery_level\": self.battery_level,\n            \"payload_capacity\": self.payload_capacity,\n            \"max_speed_m_s\": self.max_speed_m_s,\n            \"environment_data\": json.loads(self.environment_data) if self.environment_data else None\n        }\n\n    def update_from_json(self, data: dict):\n        \"\"\"Update device attributes from JSON payload.\"\"\"\n        self.device_type = data.get(\"device_type\", self.device_type)\n        self.subtype = data.get(\"subtype\", self.subtype)\n        self.zone_id = data.get(\"zone_id\", self.zone_id)\n        pos = data.get(\"position\", None)\n        if pos and isinstance(pos, dict):\n            self.position_x = pos.get(\"x\", self.position_x)\n            self.position_y = pos.get(\"y\", self.position_y)\n            self.position_z = pos.get(\"z\", self.position_z)\n        self.status = data.get(\"status\", self.status)\n        self.asset_ratio = data.get(\"asset_ratio\", self.asset_ratio)\n        reading = data.get(\"last_reading\", None)\n        if reading is not None:\n            self.last_reading = float(reading)\n        self.units = data.get(\"units\", self.units)\n        self.battery_level = data.get(\"battery_level\", self.battery_level)\n        self.payload_capacity = data.get(\"payload_capacity\", self.payload_capacity)\n        self.max_speed_m_s = data.get(\"max_speed_m_s\", self.max_speed_m_s)\n        env = data.get(\"environment_data\", None)\n        if env and isinstance(env, dict):\n            self.environment_data = json.dumps(env)\n        from datetime import datetime\n        self.last_update = datetime.utcnow()\n\n\n# Ensure all models are registered with Base\n'''

if insert_marker in content:
    new_content = content.replace(insert_marker, insert_marker + device_model, 1)
    with open('C:\\Users\\Mahantesh\\DevelopmentProjects\\Aegis\\backend\\database.py', 'w', encoding='utf-8') as f:
        f.write(new_content)
    print('SUCCESS: Device model added to database.py')
else:
    print('FAIL: Could not find insert marker in file')
    # Debug: show what we're looking for
    idx = content.find(insert_marker[:50])
    if idx >= 0:
        print(f'Found marker at position {idx}: {repr(content[idx:idx+100])}')